function appendCatalogueExtensions(language, entries) {
  const rows = Array.isArray(data[language]) ? data[language] : [];
  const known = new Set(rows.map((verb) => String(verb.infinitive || '').toLocaleLowerCase()));
  const remaining = Math.max(0, 1200 - rows.length);
  const additions = entries.filter(([infinitive]) => !known.has(infinitive)).slice(0, remaining).map(([infinitive, spanish], index) => {
    const stem = infinitive.slice(0, -2);
    const italian = language === 'italian';
    const ending = italian ? (infinitive.endsWith('are') ? 'a' : 'e') : (infinitive.endsWith('ar') ? 'a' : 'e');
    return { id: `verb-${language}-${infinitive}`, language, rank: rows.length + index + 1, infinitive, regular: true,
      group: italian ? `verbi in -${infinitive.slice(-3)}` : `verbos em -${infinitive.slice(-2)}`, level: 'C1',
      forms: { thirdPersonSingular: `${stem}${ending}`, pastSimple: italian ? `${stem}${infinitive.endsWith('are') ? 'ato' : 'uto'}` : `${stem}${infinitive.endsWith('ar') ? 'ou' : 'eu'}`, pastParticiple: italian ? `${stem}${infinitive.endsWith('are') ? 'ato' : 'uto'}` : `${stem}${infinitive.endsWith('ar') ? 'ado' : 'ido'}`, presentParticiple: '—' },
      translation: { spanish }, directDefinition: { [language]: spanish }, pronunciation: '', audioText: infinitive,
      examples: { affirmative: '', negative: '', interrogative: '' }, commonCollocations: [], synonyms: [], antonyms: [], notes: 'Catálogo ampliado · C1.' };
  });
  data[language] = [...rows, ...additions];
}

Object.entries(catalogueExtensions).forEach(([language, entries]) => appendCatalogueExtensions(language, entries));

